 now=(clock or (lambda:datetime.now(timezone.utc)))();e=snapshot.timeframe_evidence;available=tuple(v.timeframe for v in e);missing=tuple(t for t in policy.required_timeframes if t not in available);missing_mandatory=tuple(t for t in policy.mandatory_timeframes if t in missing);missing_optional=tuple(t for t in policy.optional_timeframes if t in missing);stale=tuple(v.timeframe for v in e if v.quality_status=="STALE");future=tuple(v.timeframe for v in e if v.quality_status=="FUTURE");incomplete=tuple(v.timeframe for v in e if v.quality_status=="INCOMPLETE" or v.latest_candle_complete is False);insufficient=tuple(v.timeframe for v in e if not v.history_sufficient);reference,misaligned,gap,ab,_=evaluate_timeframe_alignment(e,policy=policy);status="FUTURE" if future else "MISSING_TIMEFRAMES" if missing_mandatory else "STALE" if stale else "INCOMPLETE" if incomplete and policy.incomplete_latest_candle_behavior=="BLOCK" else "INSUFFICIENT_HISTORY" if insufficient else "MISALIGNED" if misaligned else "READY_WITH_WARNINGS" if missing_optional else "READY";blockers=("future_timeframes",) if future else ("missing_timeframes",) if missing_mandatory else ("stale_timeframes",) if stale else ("incomplete_timeframes",) if incomplete and policy.incomplete_latest_candle_behavior=="BLOCK" else ("insufficient_history",) if insufficient else ab;warnings=tuple(f"optional_timeframe_unavailable_{t}" for t in missing_optional);return MultiTimeframeQualityResultV1((quality_result_id_factory or (lambda:"mtf-quality"))(),now,snapshot.multi_timeframe_snapshot_id,status,snapshot.underlying_symbol,snapshot.exchange,policy.required_timeframes,available,missing,stale,future,incomplete,insufficient,misaligned,len(e),len(e) if status in {"READY","READY_WITH_WARNINGS"} else 0,reference,gap,blockers,warnings)
